            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "La vertu du catch, c'est d'être un spectacle excessif.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "Dans ''Iphigénie'', tout un peuple reste prisonnier de la tragédie parce que le vent ne se lève pas.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "L'enjeu tragique est ici beaucoup moins le sens de la parole que son apparition, beaucoup moins l'amour de Phèdre que son aveu.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "Phèdre est son silence même : dénouer ce silence, c'est mourir, mais aussi mourir ne peut être qu'avoir parlé.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "N'exigeons pas de l'histoire ce qu'elle ne peut nous donner : l'histoire ne nous dira jamais ce qui se passe dans un auteur au moment où il écrit.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "La beauté (contrairement à la laideur) ne peut vraiment s’expliquer : elle se dit, s’affirme, se répète en chaque partie du corps mais ne se décrit pas.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "Autrement dit, la beauté ne peut s’alléguer que sous forme d’une citation.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "J'observe avec horreur un futur antérieur dont la mort est l'enjeu.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "L'écriture est précisément cet acte qui unit dans le même travail ce qui ne pourrait être saisi ensemble dans le seul espace plat de la représentation.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "[Le sumo] Le combat ne dure qu’un éclair : le temps de laisser choir l’autre masse. Pas de crise, pas de drame, pas d’épuisement, en un mot pas de sport : le signe de la pesée, non l’éréthisme du conflit.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "Le haïku a cette propriété quelque peu fantasmagorique, que l'on s'imagine toujours pouvoir en faire soi-même facilement.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "Comme une boucle gracieuse, le haïku s'enroule sur lui-même, le sillage du signe qui semble avoir été tracé, s'efface: rien n'a été acquis, la pierre du mot a été jetée pour rien : ni vagues ni coulée du sens.", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "Qu'est-ce donc que notre visage, sinon une citation ?", Author = "Roland Barthes" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Barthes", Text = "L'ascèse (la velléité d'ascèse) s'adresse à l'autre : retourne-toi, regarde-moi, vois ce que tu as fait de moi.", Author = "Roland Barthes" },
